natalie: updated to include `retryAfter` handling and used client.request. here's the code I inserted:```js
// client-side context trim + graceful fallback example
async function fetchWithTrimAndFallback(client, prompt, budgetTokens = 1500) {
  // trim the prompt to fit the model budget
  const trimmed = truncateToBudget(prompt, budgetTokens);
  try {
    const res = await client.request({
      model: 'redwood-xl',
      input: trimmed,
      deadline: 5000, // ms
    });
    return { ok: true, data: res.output };
  } catch (err) {
    // transient 429/timeout handling: prefer fallback for interactive UX
    if (err.code === 429 || err.name === 'DeadlineExceeded') {
      const retryAfter = err.headers && err.headers['retry-after'];
      if (retryAfter) {
        // opt to surface suggested retry window to callers
        return { ok: false, retryAfter: Number(retryAfter) };
      }
      // fallback to cached/approximate response
      const cached = await readCachedSummary(prompt);
      if (cached) return { ok: false, fallback: cached };
    }
    throw err;
  }
}
```

pranav: Nice. Add a one-line comment explaining why `deadline` is preferred (it maps to the runtime SLO window and avoids hidden client-side timeouts).

